  {
    id: "sleep",
    title: "Sleep and circadian rhythm",
    why: "Sleep problems are reported by at least half of people with ADHD (CADDRA), and poor sleep on its own causes inattention and irritability. Sleep disorders can mimic ADHD (sleep apnoea, narcolepsy, insufficient sleep), aggravate it, or be part of it (delayed sleep phase, restless legs). The key questions are whether daytime problems came before the sleep problem, and whether they persist when sleep is good. Sleep also affects the choice and timing of any medicine.",
    prompts: [
      "What time do you usually go to bed, fall asleep and wake up, on work days and on free days?",
      "On holiday, sleeping as long as you like, are you still distractible, disorganised and restless?",
      "What keeps you awake: a busy mind full of different thoughts, a particular worry, or physical discomfort?",
      "Have you always been a night owl? Since what age?",
      "Do you snore loudly? Has anyone seen you stop breathing or gasp in your sleep?",
      "Do you wake unrefreshed or with headaches?",
      "Do you fall asleep without meaning to, for example reading, watching TV, in meetings or while driving?",
      "In the evening, do you get an uncomfortable urge to move your legs that eases when you move?",
      "When you laugh or feel a strong emotion, do your knees, jaw or neck ever go weak? Have you woken unable to move?",
      "Do you use screens in bed? Do you use caffeine, alcohol or cannabis to manage sleep?",
      "Do you work shifts or nights?",
      "Were you a poor sleeper as a child?",
      "Is your concentration much better after a good night's sleep?"
    ],
    items: [
      { id: "sleep_mindbusy", t: "Hard to fall asleep because the mind will not switch off", flag: "adhd", ddx: "insomnia", note: "Initial insomnia from racing thoughts is common in adult ADHD (CR235 9.3). Also screen for insomnia disorder." },
      { id: "sleep_insomnia", t: "Insomnia most nights for three months or more, with daytime effects", flag: "ddx", ddx: "insomnia", note: null },
      { id: "sleep_owl", t: "Lifelong night owl: falls asleep very late and struggles to wake for work", flag: "ddx", ddx: "dsps", note: "Delayed sleep onset is common in ADHD (Kooij et al. 2019) and can also mimic it." },
      { id: "sleep_short", t: "Regularly sleeps much less than they need on work nights", flag: "ddx", ddx: "insomnia", note: "Insufficient sleep alone causes attention and emotional-regulation problems (CADDRA). Chronic short sleep is reviewed under the insomnia differential: ask whether it is chosen, forced by work or caring, or a true inability to sleep." },
      { id: "sleep_snoring", t: "Loud snoring, witnessed pauses in breathing, or gasping", flag: "ddx", ddx: "osa", note: null },
      { id: "sleep_unrefreshed", t: "Wakes unrefreshed or with morning headaches", flag: "ddx", ddx: "osa", note: null },
      { id: "sleep_daytime", t: "Falls asleep unintentionally in the day, including while driving", flag: "risk", ddx: "osa", note: "Sleepiness at the wheel is a safety issue: discuss driving now. Consider sleep apnoea and narcolepsy." },
      { id: "sleep_cataplexy", t: "Muscle weakness with laughter or emotion, sleep paralysis, or vivid dream-like images when falling asleep", flag: "ddx", ddx: "narcolepsy", note: null },
      { id: "sleep_legs", t: "Urge to move the legs in the evening with uncomfortable feelings, eased by movement", flag: "ddx", ddx: "rls", note: "Restless legs symptoms are found in 20-33% of adults with ADHD (meta-analysis). Check ferritin." },
      { id: "sleep_shift", t: "Shift or night work disrupting sleep", flag: "ddx", ddx: "dsps", note: "Shift work disorder is a circadian rhythm disorder, reviewed with delayed sleep phase. Circadian disruption impairs concentration and affects the timing of any medicine." },
      { id: "sleep_screens", t: "Late-night screens, gaming or caffeine pushing sleep later", flag: null, ddx: null, note: null },
      { id: "sleep_child", t: "Poor sleep or bedtime battles in childhood", flag: "adhd", ddx: null, note: "Supportive only. Ask a parent if possible." },
      { id: "sleep_restless", t: "Restless, fidgety sleep reported by a bed partner", flag: "adhd", ddx: "rls", note: "Restless sleep is described in adult ADHD (Kooij et al. 2019). Ask about leg symptoms." },
      { id: "sleep_improves", t: "Daytime focus clearly recovers after good sleep or on holiday", flag: "ddx", ddx: "insomnia", note: "If daytime problems resolve with good sleep and there is no childhood history, a sleep problem may explain them better." },
      { id: "sleep_persists", t: "Still distractible and disorganised after good sleep or on holiday", flag: "adhd", ddx: null, note: null },
      { id: "sleep_osadx", t: "Already diagnosed with sleep apnoea, or using CPAP", flag: "ddx", ddx: "osa", note: "Ask whether concentration improved with treatment." }
    ]
  },
  {
    id: "strengths",
    title: "Strengths, goals and what the person wants from the assessment",
    why: "Strengths and protective factors are part of a full assessment (AADPA 2022), of the discussion after diagnosis, which includes building on strengths (NICE NG87 1.4.3), and of the shared treatment plan, which takes account of the person's goals, resilience and protective factors (NICE NG87 1.5.2). Goals turn the assessment into a plan with measurable targets (UKAAN AQAS 2024). Expectations matter too: what the person hopes a diagnosis or medicine will change, and how they would feel if ADHD is not diagnosed.",
    prompts: [
      "What are you good at? What do other people come to you for?",
      "When do things go well for you? What is different about those times?",
      "Which strategies, tools or people help you most?",
      "What do you enjoy doing in your spare time?",
      "What would you like to be different in six months' time?",
      "What do you hope this assessment will give you?",
      "What would a diagnosis mean to you? Would it change anything?",
      "How do you feel about medicine? Are there treatments you would not want?",
      "How would you feel if the assessment found something other than ADHD, or no diagnosis?",
      "Who supports you, and who could help with the plan?",
      "Is there anything about your culture, faith or background that I should understand?",
      "Do you need anything to make this assessment easier, such as breaks, written summaries or an interpreter?"
    ],
    items: [
      { id: "strengths_skills", t: "Clear strengths or talents (creative, practical, sporting, social)", flag: null, ddx: null, note: "Record them. They belong in the report and the plan." },
      { id: "strengths_hyperfocus", t: "Can focus deeply and for long periods on things of strong interest", flag: "adhd", ddx: null, note: "Hyperfocus on salient tasks is described in adult ADHD (Kooij et al. 2019). It does not argue against inattention." },
      { id: "strengths_pressure", t: "Works best under pressure, novelty or a crisis", flag: null, ddx: null, note: "A common description. Do not count it against the diagnosis." },
      { id: "strengths_support", t: "Supportive partner, family or friends", flag: null, ddx: null, note: "A protective factor." },
      { id: "strengths_strategies", t: "Has coping strategies that work (lists, alarms, routines, working alongside others, exercise)", flag: null, ddx: null, note: "Build on them in the plan." },
      { id: "strengths_exercise", t: "Regular exercise or sport that helps restlessness or mood", flag: null, ddx: null, note: null },
      { id: "strengths_goals", t: "Has specific, realistic goals for treatment", flag: null, ddx: null, note: "Use them as measurable treatment goals (UKAAN AQAS 2024)." },
      { id: "strengths_wantsmed", t: "Main goal is a prescription for stimulant medicine", flag: null, ddx: null, note: "Explore expectations. For adults, NICE NG87 1.5.15 offers medicine when significant impairment remains after environmental changes have been made and reviewed." },
      { id: "strengths_understanding", t: "Mainly wants an explanation for lifelong difficulties", flag: null, ddx: null, note: null },
      { id: "strengths_wantsadjust", t: "Main goal is support or adjustments at work or in education", flag: null, ddx: null, note: "Many practical adjustments do not depend on a formal diagnosis, and the DHSC independent review (2026) recommends a 'needs-led plus diagnosis' approach. Discuss what can start now." },
      { id: "strengths_worries", t: "Worried about stigma, labelling, or effects of a diagnosis on work, insurance or driving", flag: null, ddx: null, note: "Discuss the positives and negatives of a diagnosis (NICE NG87 1.4.3)." },
      { id: "strengths_nodx", t: "Says they would find it very hard if ADHD were not diagnosed", flag: null, ddx: null, note: "Prepare for every outcome early, and say what help is available either way (NICE NG87 1.4.4)." },
      { id: "strengths_access", t: "Needs adjustments for the assessment (breaks, written summaries, interpreter, accessible formats)", flag: null, ddx: null, note: "Tailor information to the person's needs (NICE NG87 1.4.5)." },
      { id: "strengths_culture", t: "Cultural, faith or language factors that shape how difficulties are described", flag: null, ddx: null, note: "Affects how symptoms are described and how much weight a scale score can bear." }
    ]
  }
